import { defaultHomeThemes, homeThemeIds, type HomeThemeId, type HomeThemeSettings } from '@/lib/home-theme-registry';

export type SupportedLocale = 'en' | 'ar' | 'fr' | 'es' | 'de' | 'tr' | 'pt';
type LinkLike = { href: string; label: string };

export const languagePresets: { code: SupportedLocale; name: string; nativeName: string; direction: 'ltr' | 'rtl' }[] = [
  { code: 'en', name: 'English', nativeName: 'English', direction: 'ltr' },
  { code: 'ar', name: 'Arabic', nativeName: 'العربية', direction: 'rtl' },
  { code: 'fr', name: 'French', nativeName: 'Français', direction: 'ltr' },
  { code: 'es', name: 'Spanish', nativeName: 'Español', direction: 'ltr' },
  { code: 'de', name: 'German', nativeName: 'Deutsch', direction: 'ltr' },
  { code: 'tr', name: 'Turkish', nativeName: 'Türkçe', direction: 'ltr' },
  { code: 'pt', name: 'Portuguese', nativeName: 'Português', direction: 'ltr' }
];

export function normalizeLocale(locale?: string | null): SupportedLocale {
  const value = String(locale || 'en').toLowerCase();
  return languagePresets.find((language) => value === language.code || value.startsWith(`${language.code}-`))?.code || 'en';
}

