function translateDashboardLabelByWords(label: string, locale: SupportedLocale) {
  const words = dashboardWordLabels[locale];
  if (!words) return label;
  return label.replace(/[A-Za-z]+(?:\/[A-Za-z]+)?/g, (word) => {
    if (word.includes('/')) return word.split('/').map((part) => words[part] || part).join('/');
    return words[word] || word;
  });
}

