type CopyShape = typeof copyByLocale.en;

function mergeCopy(base: CopyShape, patch: {
  site: CopyShape['site'];
  common: CopyShape['common'];
  courseCard: CopyShape['courseCard'];
  coursesPage: CopyShape['coursesPage'];
  home: CopyShape['home'];
  dashboard: CopyShape['dashboard'];
}): CopyShape {
  return {
    ...base,
    site: { ...base.site, ...patch.site },
    common: { ...base.common, ...patch.common },
    courseCard: { ...base.courseCard, ...patch.courseCard },
    coursesPage: { ...base.coursesPage, ...patch.coursesPage },
    home: { ...base.home, ...patch.home },
    dashboard: {
      roleLabels: { ...base.dashboard.roleLabels, ...patch.dashboard.roleLabels },
      navigationLabel: { ...base.dashboard.navigationLabel, ...patch.dashboard.navigationLabel }
    }
  };
}

