export function localizedCopy(locale?: string | null) {
  return extendedCopyByLocale[normalizeLocale(locale)];
}

export function localizedDashboardLabel(label: string, locale?: string | null) {
  const normalized = normalizeLocale(locale);
  if (normalized === 'en') return label;
  return dashboardExactLabels[normalized]?.[label] || translateDashboardLabelByWords(label, normalized);
}

export function localizedHomeThemes(locale?: string | null) {
  const overrides = extendedHomeThemesByLocale[normalizeLocale(locale)] || {};

  return homeThemeIds.reduce((themes, id) => {
    themes[id] = {
      ...defaultHomeThemes[id],
      ...(overrides[id] || {})
    } as HomeThemeSettings;
    return themes;
  }, {} as Record<HomeThemeId, HomeThemeSettings>);
}


